      "path": "src/runner.ts",
      "content": "/**
 * Scan orchestration and the axe-core backend for `a11y_scan`.
 *
 * Layers:
 *  - PURE scan planning: target kind detection, the URL confirmation gate,
 *    HTML page discovery, emptiness checks, and the runOnly tag set for a
 *    given `level`/`wcag21` combo (exported for tests).
 *  - A tiny in-process static server that serves local HTML files on
 *    127.0.0.1 so `@axe-core/cli` can load them headlessly.
 *  - The production {@link AxeEngine}: `createAxeCliEngine(ctx)` shells out
 *    (`ctx.subprocess`) to `npx --no-install @axe-core/cli <url> --format
 *    json --tags ...` and parses the axe result. A missing CLI surfaces as a
 *    clear `prerequisite` error instead of crashing.
 *
 * The engine is an injectable seam so offline smoke tests can drive the whole
 * pipeline against recorded axe results without a browser.
 *
 * @module dsh-a11y-scan/runner
 */

import type { Context } from '@deepseek-ai/cordis'
import type { SubprocessRuntime, SubprocessSpawnSpec } from '@deepseek-ai/dsh-subprocess'
import { readFile as fsReadFile } from 'node:fs/promises'
import { createServer, type Server, type IncomingMessage, type ServerResponse } from 'node:http'
import { basename as pathBasename, dirname, join, normalize, relative, sep } from 'node:path'

import {
  buildReport,
  renderHtml,
  renderJson,
  renderMarkdown,
  type A11yReport,
  type AxePageResult,
  type AxeRawRuleResult,
  type ScanError,
  type ScanTargetKind,
} from './report.js'

// ---------------------------------------------------------------------------
// Engine seam
// ---------------------------------------------------------------------------

export interface AxeRunRequest {
  /**
   * Directory to serve locally (abspath of the target), or null for URL
   * targets. Local pages must resolve within it.
   */
  rootDir: string | null
  /**
   * Pages to scan. `resource` is a rootDir-relative path for local pages
   * (URL path component) or the full HTTP(S) URL for remote targets.
   */
  pages: Array<{ label: string; resource: string }>
  /** runOnly tags to enforce (already computed from level/wcag21). */
  tags: string[]
  signal?: AbortSignal
}

export interface AxeRunResult {
  /** Engine identifier for the report (`axe-cli` / injected name). */
  engine: string
  pages: AxePageResult[]
}

export interface AxeEngine {
  run(request: AxeRunRequest): Promise<AxeRunResult>
}

/** Minimal filesystem surface the scanner needs (subset of `ctx.fs`). */
export interface FsAdapterTarget {
  /** Opaque backend identity. Real adapter stores the backend FsTarget. */
  handle: unknown
  /** Model/UI-facing path. */
  displayPath: string
}

export interface FsAdapterDirEntry {
  name: string
  type: 'file' | 'directory' | 'other'
  target: FsAdapterTarget
}

export interface FsAdapter {
  resolve(path: string): Promise<FsAdapterTarget>
  stat(target: FsAdapterTarget): Promise<{ type: 'file' | 'directory' | 'other'; size?: number } | undefined>
  listDir(target: FsAdapterTarget): Promise<FsAdapterDirEntry[]>
  readText(target: FsAdapterTarget): Promise<string>
  /**
   * Only used for the opt-in `reportFile` write; must be idempotent for the
   * report content (the scanner's default is strictly read-only).
   */
  writeText(target: FsAdapterTarget, content: string): Promise<void>
}

// ---------------------------------------------------------------------------
// Pure scan planning
// ---------------------------------------------------------------------------

export type ScanLevel = 'A' | 'AA' | 'AAA'

const LEVEL_TAG_SUFFIXES: Readonly<Record<ScanLevel, string[]>> = {
  A: ['a'],
  AA: ['a', 'aa'],
  AAA: ['a', 'aa', 'aaa'],
}

/**
 * The axe `runOnly.tags` set for a scan configuration. `wcag21: true` picks
 * the WCAG 2.1 tag family (`wcag21a/aa/aaa`), `false` the classic `wcag2a/
 * aa/aaa` family; `best-practice` is always included. Exported so tests can
 * assert that `level`/`wcag21` switches change the rule set (acceptance 3).
 */
export function runOnlyTags(level: ScanLevel, wcag21: boolean): string[] {
  const base = wcag21 ? 'wcag21' : 'wcag2'
  const tags = LEVEL_TAG_SUFFIXES[level].map((suffix) => `${base}${suffix}`)
  tags.push('best-practice')
  return tags
}

const URL_PATTERN = /^https?:\/\//i
const HTML_EXT = /\.(html?)$/i

export function isHttpUrl(path: string): boolean {
  return URL_PATTERN.test(path)
}

const SKIP_DIRECTORIES = new Set([
  'node_modules', '.git', '.hg', '.svn', '.idea', '.vscode',
  '__pycache__', '.venv', 'venv', '.cache', '.turbo', '.next/cache',
])

export const MAX_PAGES = 50
const MAX_DEPTH = 10

export interface ScanPage {
  /** Display label (workspace-relative path or URL). */
  label: string
  /** Path relative to the served root (URL path component), for local pages. */
  rel: string | null
  /** Adapter target for content reads (emptiness check); null for URLs. */
  target: FsAdapterTarget | null
}

export interface ResolvedTarget {
  kind: ScanTargetKind
  /** Directory used as the static server root (local), or '' for URLs. */
  rootDir: string
  pages: ScanPage[]
}

export function relPath(path: string): string {
  const normalized = path.replace(/\\/g, '/').replace(/\/+$/, '')
  const index = normalized.lastIndexOf('/')
  return index >= 0 ? normalized.slice(index + 1) : normalized
}

/**
 * Resolve the scan target into concrete pages. Pure planning: works on the
 * `FsAdapter` seam so tests can run it against fixture directories. URL
 * targets are accepted here only when `confirmUrl` is true — the acceptance
 * gate lives in {@link runA11yScanCall} for the caller that owns args.
 */
export async function resolveScanTarget(
  fs: FsAdapter,
  path: string,
): Promise<ResolvedTarget> {
  const root = await fs.resolve(path)
  const info = await fs.stat(root)

  if (isHttpUrl(path)) {
    return { kind: 'url', rootDir: '', pages: [{ label: path, rel: null, target: null }] }
  }

  if (info === undefined) {
    throw new TargetError('fs', `路径不存在: ${root.displayPath}`, false)
  }

  if (info.type === 'file') {
    if (!HTML_EXT.test(root.displayPath)) {
      throw new TargetError(
        'no-html',
        `不是 HTML 文件: ${root.displayPath}（请指定 .html/.htm 文件、目录或 URL）`,
        false,
      )
    }
    const label = root.displayPath
    const rootDir = dirname(root.displayPath)
    return {
      kind: 'file',
      rootDir,
      pages: [{ label, rel: relPath(label), target: root }],
    }
  }

  if (info.type !== 'directory') {
    throw new TargetError('scan', `无法扫描该路径类型: ${root.displayPath}`, false)
  }

  const files = await collectHtmlFiles(fs, root, 0)
  if (files.length === 0) {
    throw new TargetError(
      'no-html',
      `在 ${root.displayPath} 未发现 HTML 文件（已扫描子目录，含 dist/out/build 构建产物）。`
      + '如为纯 JS 前端项目，请先构建产生 HTML，或把 path 指向 vite/next 的构建输出目录。',
      false,
    )
  }
  return {
    kind: 'directory',
    rootDir: root.displayPath,
    pages: files.map((file) => ({
      label: file.label,
      rel: file.rel,
      target: file.target,
    })),
  }
}

interface HtmlFile {
  label: string
  rel: string
  target: FsAdapterTarget
}

async function collectHtmlFiles(fs: FsAdapter, dir: FsAdapterTarget, depth: number): Promise<HtmlFile[]> {
  const out: HtmlFile[] = []
  const walk = async (current: FsAdapterTarget, currentDepth: number): Promise<void> => {
    if (currentDepth > MAX_DEPTH || out.length >= MAX_PAGES) return
    const entries = await fs.listDir(current)
    for (const entry of entries) {
      if (out.length >= MAX_PAGES) return
      if (entry.type === 'directory') {
        if (SKIP_DIRECTORIES.has(entry.name)) continue
        await walk(entry.target, currentDepth + 1)
        continue
      }
      if (entry.type === 'file' && HTML_EXT.test(entry.name)) {
        out.push({
          label: entry.target.displayPath,
          rel: relFromDir(dir.displayPath, entry.target.displayPath),
          target: entry.target,
        })
      }
    }
  }
  await walk(dir, depth)
  out.sort((a, b) => a.label.localeCompare(b.label))
  return out
}

function relFromDir(rootDir: string, filePath: string): string {
  const root = normalize(rootDir)
  const file = normalize(filePath)
  const rel = relative(root, file)
  return rel.split(sep).join('/')
}

/** Error for user-facing scan problems (kept as `ScanError` in the report). */
export class TargetError extends Error {
  readonly error: ScanError
  constructor(kind: ScanError['kind'], message: string, retryable: boolean) {
    super(message)
    this.error = { kind, message, retryable }
  }
}

// ---------------------------------------------------------------------------
// Execution world / shell seam
// ---------------------------------------------------------------------------

/** Opaque handle stored for a real ctx.fs target. */
interface CtxFsHandle {
  target: import('@deepseek-ai/dsh-fs').FsTarget
}

/** Adapt the real `ctx.fs` service to the {@link FsAdapter} seam. */
export function adaptCtxFs(ctx: Context): FsAdapter {
  const toTarget = (target: FsAdapterTarget): import('@deepseek-ai/dsh-fs').FsTarget => {
    return (target.handle as CtxFsHandle).target
  }
  return {
    async resolve(path) {
      const target = await ctx.fs.resolve(path)
      return { handle: { target } satisfies CtxFsHandle, displayPath: target.displayPath }
    },
    async stat(target) {
      const info = await ctx.fs.stat(toTarget(target))
      if (info === undefined) return undefined
      return { type: info.type, size: info.size }
    },
    async listDir(target) {
      const entries = await ctx.fs.listDir(toTarget(target))
      return entries.map((entry) => ({
        name: entry.name,
        type: entry.type,
        target: {
          handle: { target: entry.target } satisfies CtxFsHandle,
          displayPath: entry.target.displayPath,
        },
      }))
    },
    async readText(target) {
      return ctx.fs.readText(toTarget(target))
    },
    async writeText(target, content) {
      await ctx.fs.writeText(toTarget(target), content)
    },
  }
}

// ---------------------------------------------------------------------------
// Static server (serves local pages to the headless browser / axe CLI)
// ---------------------------------------------------------------------------

const MIME: Readonly<Record<string, string>> = {
  '.html': 'text/html; charset=utf-8',
  '.htm': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.mjs': 'text/javascript; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.svg': 'image/svg+xml',
  '.webp': 'image/webp',
  '.ico': 'image/x-icon',
  '.txt': 'text/plain; charset=utf-8',
}

export interface StaticServer {
  /** Base URL, e.g. `http://127.0.0.1:49123`. */
  origin: string
  /** Build a URL for a page's relative path. */
  urlFor(rel: string): string
  close(): Promise<void>
}

/**
 * Serve files under `rootDir` on an ephemeral 127.0.0.1 port. Requests are
 * confined to `rootDir` (path traversal is rejected).
 */
export async function startStaticServer(rootDir: string): Promise<StaticServer> {
  const server: Server = createServer((req: IncomingMessage, res: ServerResponse) => {
    const requestUrl = req.url ?? '/'
    // Malformed percent-encoding (e.g. `/%zz`) makes decodeURIComponent throw;
    // never let a request crash the scan server (or the host process).
    let pathname: string
    try {
      pathname = decodeURIComponent(requestUrl.split('?')[0] ?? '/')
    } catch {
      res.writeHead(400, { 'Content-Type': 'text/plain' })
      res.end('bad request')
      return
    }
    // `normalize` keeps a trailing separator; strip it so confinement checks
    // and `root + sep` joins are exact.
    const root = normalize(rootDir).replace(/[/\\]+$/, '')
    const safe = normalize(join(root, pathname))
    if (safe === root || !safe.startsWith(`${root}${sep}`)) {
      res.writeHead(404, { 'Content-Type': 'text/plain' })
      res.end('not found')
      return
    }
    void serveFile(safe, res)
  })
  await new Promise<void>((resolveListen, rejectListen) => {
    server.once('error', rejectListen)
    server.listen(0, '127.0.0.1', () => resolveListen())
  })
  const address = server.address()
  const port = address !== null && typeof address === 'object' ? address.port : 0
  const origin = `http://127.0.0.1:${port}`
  return {
    origin,
    urlFor(rel) {
      return `${origin}/${rel.split(sep).join('/')}`
    },
    close() {
      return new Promise<void>((resolveClose) => {
        server.close(() => resolveClose())
      })
    },
  }
}

function serveFile(absPath: string, res: ServerResponse): void {
  void fsReadFile(absPath)
    .then((content) => {
      const ext = (pathBasename(absPath).match(/\.[a-z0-9]+$/i)?.[0] ?? '').toLowerCase()
      res.writeHead(200, { 'Content-Type': MIME[ext] ?? 'application/octet-stream' })
      res.end(content)
    })
    .catch(() => {
      res.writeHead(404, { 'Content-Type': 'text/plain' })
      res.end('not found')
    })
}

// ---------------------------------------------------------------------------
// Production engine: @axe-core/cli over the subprocess seam
// ---------------------------------------------------------------------------

const AXE_CLI_OUTPUT_CAP = 8 * 1024 * 1024
const AXE_CLI_SPILL_CAP = 64 * 1024 * 1024
const AXE_CLI_GRACE_MS = 5_000

/**
 * The production engine: serves the target directory on 127.0.0.1 and shells
 * out to `npx --no-install @axe-core/cli <url> --format json --tags …` for
 * each page (sequential, bounded by MAX_PAGES). Parse failures and a missing
 * CLI surface as classified {@link ScanError}s.
 *
 * Prerequisite (documented in README): `@axe-core/cli` resolves from the
 * target directory (`npm i -D @axe-core/cli`, which pulls puppeteer/Chrome).
 * The tool never installs it automatically — a clear error tells the user how.
 */
export function createAxeCliEngine(ctx: Context): AxeEngine {
  const subprocess = ctx.subprocess
  return {
    async run(request) {
      const server = request.rootDir !== null && request.pages.some((page) => !isHttpUrl(page.resource))
        ? await startStaticServer(request.rootDir)
        : null
      const cwd = request.rootDir ?? process.cwd()
      try {
        const pageResults: AxePageResult[] = []
        for (const page of request.pages) {
          if (request.signal?.aborted === true) break
          const url = isHttpUrl(page.resource)
            ? page.resource
            : (server as StaticServer).urlFor(page.resource)
          pageResults.push(await runSinglePage(subprocess, { label: page.label, url }, request.tags, cwd, request.signal))
        }
        return { engine: 'axe-cli', pages: pageResults }
      } finally {
        if (server !== null) await server.close()
      }
    },
  }
}

async function runSinglePage(
  subprocess: SubprocessRuntime,
  page: { label: string; url: string },
  tags: readonly string[],
  cwd: string,
  signal?: AbortSignal,
): Promise<AxePageResult> {
  const spec: SubprocessSpawnSpec = {
    argv: ['npx', '--no-install', '@axe-core/cli', page.url, '--format', 'json', '--tags', tags.join(',')],
    cwd,
    stdio: {
      stdin: 'ignore',
      stdout: { maxBytes: AXE_CLI_OUTPUT_CAP, spill: { maxBytes: AXE_CLI_SPILL_CAP } },
      stderr: { maxBytes: 2 * 1024 * 1024 },
    },
    graceMs: AXE_CLI_GRACE_MS,
    signal,
  }
  const handle = subprocess.spawn(spec)
  const outcome: Awaited<typeof handle.done> = await handle.done
  const stdout = handle.collected.stdout?.readFrom(0).text ?? ''
  const stderr = handle.collected.stderr?.readFrom(0).text ?? ''

  if (outcome.exitCode !== 0) {
    const detail = stderr.trim() !== '' ? ` stderr: ${stderr.trim().slice(0, 500)}` : ''
    throw new TargetError(
      'prerequisite',
      `axe 未成功运行（exit=${outcome.exitCode ?? outcome.signal ?? 'spawn-failed'}）。`
      + '前置依赖：在目标项目执行 `npm i -D @axe-core/cli`（会安装 puppeteer/Chrome 做无头扫描），'
      + `或先运行 \`npx @axe-core/cli --help\` 验证。${detail}`,
      true,
    )
  }

  if (stdout.trim() === '') {
    throw new TargetError('axe', `axe 未输出可解析结果（页面 ${page.label} 可能为空白/仅 JS 渲染）。`, true)
  }

  let parsed: unknown
  try {
    parsed = JSON.parse(stdout)
  } catch {
    throw new TargetError('axe', `axe 输出不是合法 JSON（页面 ${page.label}）。`, true)
  }
  const results = Array.isArray(parsed) ? parsed[0] : parsed
  const axe = results as {
    url?: string
    violations?: AxeRawRuleResult[]
    incomplete?: AxeRawRuleResult[]
  }
  if (typeof axe !== 'object' || axe === null || !Array.isArray(axe.violations)) {
    throw new TargetError('axe', `axe 返回了意外的结果结构（页面 ${page.label}）。`, false)
  }
  return {
    label: page.label,
    url: page.url,
    violations: axe.violations ?? [],
    incomplete: axe.incomplete ?? [],
  }
}

// ---------------------------------------------------------------------------
// Orchestration: the full scan call
// ---------------------------------------------------------------------------

export interface A11yScanArgs {
  /** Project directory, single HTML file, or URL (URL needs `confirmUrl`). */
  path?: string
  /** Conformance level; controls the axe runOnly tag family. Default AA. */
  level?: ScanLevel
  /** WCAG 2.1 tag family vs classic wcag2 tags. Default true. */
  wcag21?: boolean
  /** Report format. Default md. */
  out?: 'md' | 'html' | 'json'
  /** Explicit user confirmation for URL targets. Default false. */
  confirmUrl?: boolean
  /** Optional output file path for the rendered report (opt-in write). */
  reportFile?: string
}

export interface RunA11yScanOptions {
  fs: FsAdapter
  engine: AxeEngine
  signal?: AbortSignal
}

export interface A11yScanResult {
  report: A11yReport
  rendered: string
  out: 'md' | 'html' | 'json'
  /** Where the report was written, when `reportFile` was requested and succeeded. */
  reportPath: string | null
}

/**
 * The whole scan call: resolve the target, apply the URL confirmation gate,
 * check page emptiness, run the engine, and assemble + render the report.
 * Expected failures (missing path, no HTML, empty file, missing axe CLI,
 * unconfirmed URL) land in `report.errors`; this function only throws for
 * genuinely broken inputs.
 */
export async function runA11yScanCall(args: A11yScanArgs, options: RunA11yScanOptions): Promise<A11yScanResult> {
  const { fs, engine, signal } = options
  const level = args.level ?? 'AA'
  const wcag21 = args.wcag21 ?? true
  const out = args.out ?? 'md'
  const target = args.path ?? '.'
  const tags = runOnlyTags(level, wcag21)
  const errors: ScanError[] = []
  const timestamp = new Date().toISOString()

  let kind: ScanTargetKind = 'file'
  let rootDir: string | null = null
  let engineName = ''
  const pagesToScan: Array<{ label: string; resource: string }> = []
  const pages: AxePageResult[] = []

  if (isHttpUrl(target)) {
    kind = 'url'
    if (args.confirmUrl !== true) {
      errors.push({
        kind: 'url-confirmation-required',
        message:
          'URL 扫描需要用户显式确认：请先确认目标 URL 的可信度与网络访问策略，'
          + '再以 confirmUrl: true 重试。本地文件优先，避免对不可信站点发起浏览器扫描。',
        retryable: true,
      })
    } else {
      pagesToScan.push({ label: target, resource: target })
    }
  } else {
    let resolved: ResolvedTarget | undefined
    try {
      resolved = await resolveScanTarget(fs, target)
    } catch (err) {
      if (err instanceof TargetError) {
        errors.push(err.error)
      } else {
        errors.push({ kind: 'scan', message: `解析目标失败: ${String(err)}`, retryable: false })
      }
    }
    if (resolved !== undefined) {
      kind = resolved.kind
      rootDir = resolved.rootDir
      for (const page of resolved.pages) {
        if (page.target === null) {
          pagesToScan.push({ label: page.label, resource: page.label })
          continue
        }
        const text = await fs.readText(page.target)
        if (text.trim() === '') {
          errors.push({ kind: 'empty-file', message: `页面为空（无内容）: ${page.label}`, retryable: false })
          continue
        }
        pagesToScan.push({ label: page.label, resource: page.rel ?? page.label })
      }
    }
  }

  if (pagesToScan.length > 0) {
    try {
      const result = await engine.run({ rootDir, pages: pagesToScan, tags, signal })
      pages.push(...result.pages)
      engineName = result.engine
    } catch (err) {
      if (err instanceof TargetError) {
        errors.push(err.error)
      } else {
        errors.push({ kind: 'axe', message: `扫描引擎执行失败: ${String(err)}`, retryable: true })
      }
    }
  }

  const report = buildReport({
    meta: { target, kind, level, wcag21, tags, engine: engineName !== '' ? engineName : 'not-run', timestamp },
    pages,
    errors,
  })
  let rendered = renderReport(report, out)

  // Opt-in report write; the default remains strictly read-only.
  let reportPath: string | null = null
  if (args.reportFile !== undefined && args.reportFile !== '') {
    try {
      const target = await fs.resolve(args.reportFile)
      await fs.writeText(target, rendered)
      reportPath = target.displayPath
    } catch (err) {
      report.errors.push({
        kind: 'fs',
        message: `写入报告文件失败（${args.reportFile}）: ${String(err)}`,
        retryable: true,
      })
      rendered = renderReport(report, out)
    }
  }

  return {
    report,
    rendered,
    out,
    reportPath,
  }
}

/** Render the report in the requested format. */
export function renderReport(report: A11yReport, out: 'md' | 'html' | 'json'): string {
  if (out === 'html') return renderHtml(report)
  if (out === 'json') return renderJson(report)
  return renderMarkdown(report)
