/** Highest conformance level derived from an axe rule's own wcag tags. */
const TAG_LEVEL: Readonly<Record<string, 'A' | 'AA' | 'AAA'>> = {
  wcag2a: 'A', wcag21a: 'A',
  wcag2aa: 'AA', wcag21aa: 'AA',
  wcag2aaa: 'AAA', wcag21aaa: 'AAA',
}

const UNKNOWN_TITLE = 'WCAG 2.1 成功标准'

/**
 * WCAG 2.1 references for one axe rule. Curated map first; falls back to the
 * rule's own wcag tags (best matching criterion displayed generically).
 */
export function wcagReferences(ruleId: string, tags: readonly string[]): WcagReference[] {
  const curated = WCAG_MAP[ruleId]
  if (curated !== undefined) {
    return [{
      sc: curated.sc,
      level: curated.level,
      title: curated.title,
      quickrefUrl: quickrefAnchor(curated.sc),
    }]
  }
  const tagged = tags
    .filter((tag): tag is keyof typeof TAG_LEVEL => tag in TAG_LEVEL)
    .map((tag) => TAG_LEVEL[tag])
  const best = tagged
    .sort((a, b) => rankLevel(b) - rankLevel(a))[0]
  const sc = best === undefined ? '（见 axe 规则说明）' : `（${best} 级）`
  return [{
    sc,
    level: best ?? 'AA',
    title: UNKNOWN_TITLE,
    quickrefUrl: 'https://www.w3.org/WAI/WCAG21/quickref/',
  }]
}

/** Fix suggestions for one axe rule (curated; falls back to a generic path). */
export function fixSuggestions(ruleId: string, helpUrl: string): FixSuggestion {
  const curated = WCAG_MAP[ruleId]
  const steps = curated !== undefined
    ? curated.fix
    : [
      '对照 axe 规则说明确认预期行为后修正标记/结构',
      '修复后在真实浏览器（或 axe 重跑）中验证不再命中该规则',
    ]
  const links = [`axe 规则: ${helpUrl || `https://dequeuniversity.com/rules/axe/4.10/${ruleId}`}`]
  return { steps, links }
}

function rankLevel(level: 'A' | 'AA' | 'AAA'): number {
  return level === 'A' ? 0 : level === 'AA' ? 1 : 2
}

/** Build a WCAG 2.1 quick-ref anchor URL for a criterion like `1.4.3`. */
export function quickrefAnchor(sc: string): string {
  const code = sc.replace(/\./g, '.')
  return `https://www.w3.org/WAI/WCAG21/quickref/#${code}`
}

// ---------------------------------------------------------------------------
// Normalized report model
// ---------------------------------------------------------------------------

export interface NormalizedNode {
  /** Readable CSS selector for the failing element. */
  selector: string
  /** Element HTML as axe saw it (trimmed). */
  html: string
  /** Concise "why" — axe check messages or the failureSummary. */
  summary: string
  /** axe failureSummary verbatim when present. */
  failureSummary: string
}

export interface NormalizedViolation {
  ruleId: string
  /** axe impact; `null` for rules axe rates as best-practice-only. */
  impact: AxeImpact | null
  /** Sort key: critical 0 … minor 3, unknown last. */
  impactRank: number
  title: string
  description: string
  helpUrl: string
  /** WCAG 2.1 references (curated or tag-derived). */
  wcag: WcagReference[]
  fix: FixSuggestion
  /** Failing elements on this page. */
  nodes: NormalizedNode[]
  /** Display path / URL of the page this violation was found on. */
  page: string
}

export interface ManualReviewItem {
  id: string
  title: string
  /** WCAG 2.1 criterion covered or "—". */
  sc: string
  detail: string
}

export interface Summary {
  pages: number
  total: number
  critical: number
  serious: number
  moderate: number
  minor: number
  unknown: number
  /** Count of axe "incomplete" checks (need manual judgement). */
  incomplete: number
  /** Per-rule occurrence counts, most frequent first. */
  byRule: Array<{ ruleId: string; count: number }>
}

export type ScanErrorKind =
  | 'url-confirmation-required'
  | 'prerequisite'
  | 'axe'
  | 'scan'
  | 'fs'
  | 'empty-file'
  | 'no-html'

export interface ScanError {
  kind: ScanErrorKind
  message: string
  /** True when a retry after fixing prerequisites could succeed. */
  retryable: boolean
}

export type ScanTargetKind = 'file' | 'directory' | 'url'

export interface ReportMeta {
  target: string
  kind: ScanTargetKind
  level: 'A' | 'AA' | 'AAA'
  wcag21: boolean
  /** runOnly tags the engine was told to use. */
  tags: string[]
  engine: string
  timestamp: string
}

export interface A11yReport {
  scanned: ReportMeta & { pages: string[] }
  violations: NormalizedViolation[]
  /** axe checks that could not be auto-judged (still worth manual review). */
  incomplete: NormalizedViolation[]
  summary: Summary
  manualReview: ManualReviewItem[]
  errors: ScanError[]
}

const IMPACT_RANK: Readonly<Record<string, number>> = {
  critical: 0, serious: 1, moderate: 2, minor: 3,
}

export function impactRank(impact: AxeImpact | null): number {
  return impact === null ? 4 : IMPACT_RANK[impact] ?? 4
}

function normalizeRule(rule: AxeRawRuleResult, page: string): NormalizedViolation {
  const impact = rule.impact ?? null
  return {
    ruleId: rule.id,
    impact,
    impactRank: impactRank(impact),
    title: rule.help || rule.id,
    description: rule.description,
    helpUrl: rule.helpUrl,
    wcag: wcagReferences(rule.id, rule.tags),
    fix: fixSuggestions(rule.id, rule.helpUrl),
    nodes: rule.nodes.map((node) => normalizeNode(node)),
    page,
  }
}

function normalizeRules(
  results: readonly AxeRawRuleResult[],
  page: string,
): NormalizedViolation[] {
  return results.map((rule) => normalizeRule(rule, page))
}

function normalizeNode(node: AxeRawNode): NormalizedNode {
  const messages: string[] = []
  for (const group of [node.any, node.all, node.none]) {
    for (const check of group ?? []) {
      if (typeof check.message === 'string' && check.message.length > 0) messages.push(check.message)
    }
  }
  return {
    selector: (node.target ?? []).join(' '),
    html: truncate(node.html ?? '', 240),
    summary: node.failureSummary ?? messages[0] ?? '（无摘要）',
    failureSummary: node.failureSummary ?? '',
  }
}

function truncate(text: string, max: number): string {
  if (text.length <= max) return text.trim()
  return `${text.slice(0, max).trim()}…`
}

const IMPACT_LABEL: Readonly<Record<number, string>> = {
  0: 'critical', 1: 'serious', 2: 'moderate', 3: 'minor', 4: 'unknown',
}

/**
 * Assemble the canonical report from per-page axe results. Pure: sorting,
 * counting, and error aggregation only.
 */
export function buildReport(input: {
  meta: ReportMeta
  pages: AxePageResult[]
  errors: ScanError[]
}): A11yReport {
  const { meta } = input
  const violations: NormalizedViolation[] = []
  const incomplete: NormalizedViolation[] = []
  for (const page of input.pages) {
    violations.push(...normalizeRules(page.violations, page.label))
    incomplete.push(...normalizeRules(page.incomplete, page.label))
  }
  violations.sort(compareViolations)
  incomplete.sort(compareViolations)

  const counts = { critical: 0, serious: 0, moderate: 0, minor: 0, unknown: 0 }
  for (const violation of violations) {
    const key = IMPACT_LABEL[violation.impactRank] ?? 'unknown'
    counts[key as keyof typeof counts] += 1
  }
  const byRule = new Map<string, number>()
  for (const violation of violations) {
    byRule.set(violation.ruleId, (byRule.get(violation.ruleId) ?? 0) + 1)
  }

  return {
    scanned: { ...meta, pages: input.pages.map((page) => page.label) },
    violations,
    incomplete,
    summary: {
      pages: input.pages.length,
      total: violations.length,
      critical: counts.critical,
      serious: counts.serious,
      moderate: counts.moderate,
      minor: counts.minor,
      unknown: counts.unknown,
      incomplete: incomplete.length,
      byRule: [...byRule.entries()]
        .map(([ruleId, count]) => ({ ruleId, count }))
        .sort((a, b) => b.count - a.count || a.ruleId.localeCompare(b.ruleId)),
    },
    manualReview: MANUAL_REVIEW_CHECKLIST,
    errors: input.errors,
  }
}

function compareViolations(a: NormalizedViolation, b: NormalizedViolation): number {
  return a.impactRank - b.impactRank
    || a.ruleId.localeCompare(b.ruleId)
    || a.page.localeCompare(b.page)
}

