// ---------------------------------------------------------------------------
// Rendering
// ---------------------------------------------------------------------------

export function renderMarkdown(report: A11yReport): string {
  const lines: string[] = []
  const m = report.scanned
  lines.push('# 无障碍（WCAG）扫描报告')
  lines.push('')
  lines.push(
    `- **目标**: \`${m.target}\`（${m.kind}）｜级别 **${m.level}** ｜WCAG 2.1 规则集: \`${m.wcag21 ? 'on' : 'off'}\``
    + `｜引擎: \`${m.engine}\`｜页面: ${m.pages.length}｜时间: ${m.timestamp}`,
  )
  const s = report.summary
  lines.push(
    `- **汇总**: 共 **${s.total}** 项违规　`
    + `critical **${s.critical}** / serious **${s.serious}** / moderate **${s.moderate}** / minor **${s.minor}**`
    + `${s.unknown > 0 ? ` / unknown ${s.unknown}` : ''}　`
    + `（需人工复核的 axe incomplete: ${s.incomplete}）`,
  )
  lines.push('')

  if (report.errors.length > 0) {
    lines.push('> ⚠️ 扫描未完整执行：')
    for (const error of report.errors) {
      lines.push(`> - \`${error.kind}\`: ${error.message}`)
    }
    lines.push('')
  }

  if (s.total === 0 && s.incomplete === 0) {
    lines.push('**未发现违规** — 本页未命中任何所选规则集（不含人工复核清单中的感知/操作项）。')
    lines.push('')
  }

  const grouped = distinctBy(report.violations, (v) => v.ruleId)
  for (const violation of grouped) {
    lines.push(`### [${violation.impact ?? 'unknown'}] \`${violation.ruleId}\` — ${violation.title}`)
    lines.push('')
    const wcag = violation.wcag.map((w) => `[${w.sc} ${w.title} (${w.level})](${w.quickrefUrl})`).join('、')
    lines.push(`- **WCAG 2.1**: ${wcag}`)
    if (violation.description !== '') lines.push(`- **说明**: ${violation.description}`)
    lines.push(`- **axe 规则**: [${violation.ruleId}](${violation.helpUrl || '#'})`)
    lines.push('')
    lines.push('| 页面 | 元素 | 为什么失败 |')
    lines.push('| --- | --- | --- |')
    for (const node of violation.nodes) {
      lines.push(`| ${escapeCell(violation.page)} | \`${escapeCell(node.selector)}\` | ${escapeCell(node.summary)} |`)
    }
    lines.push('')
    lines.push('**修复建议**（未自动修改任何文件，确认后执行）：')
    for (const step of violation.fix.steps) {
      lines.push(`- ${step}`)
    }
    for (const link of violation.fix.links ?? []) {
      lines.push(`- ${link}`)
    }
    lines.push('')
  }

  if (report.incomplete.length > 0) {
    lines.push('### ⚠️ axe 无法自动判定的项（incomplete，需人工复核）')
    lines.push('')
    for (const violation of report.incomplete) {
      const wcag = violation.wcag.map((w) => `${w.sc}(${w.level})`).join('、')
      lines.push(
        `- [${violation.impact ?? 'unknown'}] \`${violation.ruleId}\`（WCAG: ${wcag}）— ${violation.title}`
        + `（${violation.nodes.length} 个元素，如 ${escapeCell(violation.nodes[0]?.selector ?? '')}）`,
      )
    }
    lines.push('')
  }

  lines.push('### 需人工复核清单（自动化覆盖不了的感知/操作项）')
  lines.push('')
  for (const item of MANUAL_REVIEW_CHECKLIST) {
    lines.push(`- **${item.title}**（WCAG ${item.sc}）：${item.detail}`)
  }
  lines.push('')
  lines.push(
    '_只读扫描：本工具不修改任何代码/文件；修复建议需人工确认后执行。'
    + '规则集由 axe-core 提供（MPL-2.0），字段模型参考 wshobson/agents accessibility-compliance（MIT）。_',
  )
  return lines.join('\n')
}

function distinctBy<T>(items: readonly T[], key: (item: T) => string): T[] {
  const seen = new Set<string>()
  const out: T[] = []
  for (const item of items) {
    const k = key(item)
    if (seen.has(k)) continue
    seen.add(k)
    out.push(item)
  }
  return out
}

function escapeCell(text: string): string {
  return text.replace(/\|/g, '\\|').replace(/\n/g, ' ')
}

export interface HtmlProjection {
  scanned: ReportMeta & { pages: string[] }
  summary: Summary
  violations: Array<{
    ruleId: string
    impact: AxeImpact | null
    impactRank: number
    title: string
    description: string
    helpUrl: string
    wcag: WcagReference[]
    fix: { steps: string[]; links?: string[] }
    nodes: NormalizedNode[]
    page: string
  }>
  incomplete: NormalizedViolation[]
  manualReview: ManualReviewItem[]
  errors: ScanError[]
  renderedAt: string
}

/** Build the data blob embedded in the self-contained HTML report. */
export function buildHtmlProjection(report: A11yReport): HtmlProjection {
  return {
    scanned: report.scanned,
    summary: report.summary,
    violations: report.violations,
    incomplete: report.incomplete,
    manualReview: report.manualReview,
    errors: report.errors,
    renderedAt: report.scanned.timestamp,
  }
}

const TEMPLATE_DATA_MARKER = '__A11Y_DATA_JSON__'

/**
 * Render the report into the self-contained template. The template contains
 * inline CSS/JS and zero external resources; the projection is embedded as a
 * JSON script and rendered client-side, so the file opens from disk.
 */
export function renderHtml(report: A11yReport, template: string = defaultTemplateHtml): string {
  const json = JSON.stringify(buildHtmlProjection(report))
    // Never let `</script>` inside element HTML break the embed.
    .replace(/</g, '\\u003c')
  if (!template.includes(TEMPLATE_DATA_MARKER)) {
    throw new Error('report template is missing the data marker __A11Y_DATA_JSON__')
  }
  return template.replace(TEMPLATE_DATA_MARKER, json)
}

export function renderJson(report: A11yReport): string {
  return JSON.stringify(report, null, 2)
}

/**
 * Replayable presentation projection: a compact, card-friendly view of the
 * report persisted under the tool-result meta. Pure function of
 * `(args, value)`.
 */
export function buildPresentationMeta(_args: unknown, value: unknown): JsonValue {
  const report = value as unknown as A11yReport
  return {
    target: report.scanned.target,
    kind: report.scanned.kind,
    level: report.scanned.level,
    wcag21: report.scanned.wcag21,
    summary: report.summary,
    topRules: report.summary.byRule.slice(0, 8),
    manualReviewCount: report.manualReview.length,
    incompleteCount: report.summary.incomplete,
    errorCount: report.errors.length,
  } as unknown as JsonValue
}

