<script>
(function () {
  var data = JSON.parse(document.getElementById('a11y-data').textContent);
  var esc = function (s) {
    return String(s == null ? '' : s).replace(/[&<>"]/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c];
    });
  };
  var s = data.scanned;
  document.getElementById('meta').textContent =
    '目标: ' + s.target + ' (' + s.kind + ') ｜ 级别: ' + s.level +
    ' ｜ WCAG 2.1 规则集: ' + (s.wcag21 ? 'on' : 'off') +
    ' ｜ 引擎: ' + s.engine + ' ｜ 页面: ' + s.pages.length + ' ｜ ' + s.timestamp;

  var sum = data.summary;
  var sumEl = document.getElementById('summary');
  var chips = [
    ['违规总数', sum.total, ''],
    ['critical', sum.critical, 'critical'],
    ['serious', sum.serious, 'serious'],
    ['moderate', sum.moderate, 'moderate'],
    ['minor', sum.minor, 'minor'],
    ['incomplete', sum.incomplete, '']
  ];
  chips.forEach(function (c) {
    var d = document.createElement('div');
    d.className = 'chip ' + c[2];
    var n = document.createElement('span');
    n.className = 'n';
    n.textContent = c[1];
    var l = document.createElement('span');
    l.className = 'l';
    l.textContent = c[0];
    d.appendChild(n); d.appendChild(l);
    sumEl.appendChild(d);
  });

  var errEl = document.getElementById('errors');
  (data.errors || []).forEach(function (e) {
    var d = document.createElement('div');
    d.className = 'error';
    d.textContent = '[' + e.kind + '] ' + e.message;
    errEl.appendChild(d);
  });

  var box = document.getElementById('violations');
  (data.violations || []).forEach(function (v) {
    var card = document.createElement('section');
    card.className = 'violation ' + (v.impact || 'unknown');
    var h = document.createElement('h3');
    h.innerHTML = '[' + esc(v.impact || 'unknown') + '] <code>' + esc(v.ruleId) + '</code> — ' + esc(v.title);
    card.appendChild(h);
    var tags = v.wcag.map(function (w) {
      return '<span class="tag"><a href="' + esc(w.quickrefUrl) + '" target="_blank" rel="noopener">WCAG ' +
        esc(w.sc) + ' ' + esc(w.title) + ' (' + esc(w.level) + ')</a></span>';
    }).join('');
    var rules = '<span class="tag"><a href="' + esc(v.helpUrl || '#') + '" target="_blank" rel="noopener">axe 规则说明</a></span>';
    var p = document.createElement('p');
    p.innerHTML = tags + rules;
    card.appendChild(p);
    var rows = v.nodes.map(function (n) {
      return '<tr><td>' + esc(n.page) + '</td><td><code>' + esc(n.selector) + '</code></td>' +
        '<td>' + esc(n.summary) + '</td></tr>';
    }).join('');
    var table = '<div class="nodes"><table><thead><tr><th>页面</th><th>元素</th><th>为什么失败</th></tr></thead><tbody>' +
      rows + '</tbody></table></div>';
    card.insertAdjacentHTML('beforeend', table);
    var fix = '<div class="fix"><strong>修复建议（需人工确认后执行）：</strong><ul>' +
      v.fix.steps.map(function (st) { return '<li>' + esc(st) + '</li>'; }).join('') + '</ul></div>';
    card.insertAdjacentHTML('beforeend', fix);
    box.appendChild(card);
  });
  if (!data.violations || data.violations.length === 0) {
